{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Use only as formal authority context; it does not show any 2022 nuclear-risk choice."
        },
        {
          "evidence_id": "E0008",
          "reason": "This is general crisis-de-escalation diplomacy, not nuclear command-and-control conduct."
        },
        {
          "evidence_id": "E0011",
          "reason": "This is a civil-energy milestone, not evidence of existential-risk governance."
        },
        {
          "evidence_id": "E0012",
          "reason": "Sanctions risk is an external constraint on Rooppur, not ruler-attributed safety action."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 regulator or BAERA evidence on Rooppur safety staffing, inspections, or corrective actions",
          "lenses": ["1B.3", "1B.7", "1B.9"],
          "best_source_or_query_direction": "IAEA mission report, BAERA filings, or Rooppur regulatory inspection records from 2022",
          "why_it_matters": "Would turn the chapter from mostly posture-and-treaty evidence into a firmer ruler-attributed safety record."
        }
      ],
      "reason": "Usable and mostly fair for a limited-exposure non-nuclear state, with a clear anti-proliferation posture and only a small amount of over-broad civil-nuclear context that should not be read as direct weapon-risk conduct."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0023",
          "reason": "UN peacekeeping contribution is institutional state conduct, not a direct ruler-level conflict choice."
        },
        {
          "evidence_id": "E0024",
          "reason": "This duplicates the peacekeeping-contribution context and is not personal crisis conduct."
        },
        {
          "evidence_id": "E0025",
          "reason": "Peace-support activity is relevant context, but it is not a ruler-directed interstate peace decision."
        },
        {
          "evidence_id": "E0026",
          "reason": "This is humanitarian refugee management, not a negotiated peace settlement or war choice."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on Hasina's personal role in 2022 conflict tradeoffs, especially the rationale for the Ukraine abstention and Rohingya diplomacy",
          "lenses": ["2B.1", "2B.7", "2B.10"],
          "best_source_or_query_direction": "Cabinet minutes, MFA instructions, or authoritative contemporaneous interviews and briefings around the two Ukraine votes and Rohingya talks",
          "why_it_matters": "Would sharpen attribution and distinguish state posture from ruler choice."
        }
      ],
      "reason": "The package fairly shows a limited-exposure, mostly restraint-oriented foreign-policy posture with a real contrary data point in the abstention; the main weakness is personal attribution, not the balance of conduct."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0042",
          "reason": "A formal complaint channel is only remedy context; it does not prove effective accountability."
        },
        {
          "evidence_id": "E0041",
          "reason": "This is broad country-level context with partial offsets, not a clean rebuttal to the repression record."
        },
        {
          "evidence_id": "E0036",
          "reason": "Treat the disappearance figures as unresolved allegations and reporting statistics, not adjudicated findings."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct command-chain evidence for the specific 2022 protest and disappearance episodes",
          "lenses": ["3B.1", "3B.2", "3B.9"],
          "best_source_or_query_direction": "UN special procedures documents, court records, or detailed domestic inquiry materials on the 7 December crackdown and disappearance cases",
          "why_it_matters": "Would tighten attribution and avoid relying almost entirely on monitor-level summaries."
        }
      ],
      "reason": "The chapter is well supported and appropriately includes contrary evidence, but it still leans heavily on advocacy and monitor reporting rather than direct command records."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0045",
          "reason": "This mixes inherited 2018 baseline with 2022 restrictions; use it as context, not as a standalone 2022 proof."
        },
        {
          "evidence_id": "E0047",
          "reason": "Residual online mobilization is a narrow counterpoint, not proof of broad political openness."
        },
        {
          "evidence_id": "E0050",
          "reason": "This repeats the same narrow online-mobilization point and should not be overweighted against the broader crackdown record."
        }
      ],
      "material_gaps": [
        {
          "gap": "More direct 2022 evidence on election administration, judiciary independence, and chain of responsibility for opposition-policing and EC selection",
          "lenses": ["4B.2", "4B.4", "4B.6", "4B.9"],
          "best_source_or_query_direction": "Election Commission records, domestic observer reports, and direct reporting on 2022 appointments and protest policing",
          "why_it_matters": "Would separate tolerated competition from genuine political openness."
        }
      ],
      "reason": "Strong enough to present a constrained political-freedom environment with some residual contestation, though it would benefit from cleaner separation of inherited baseline, 2022 conduct, and narrow positive exceptions."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0055",
          "reason": "This is appointment and capacity context, not proof of Hasina's own economic stewardship."
        },
        {
          "evidence_id": "E0064",
          "reason": "Country-level corruption commentary is context, not personal economic conduct."
        },
        {
          "evidence_id": "E0065",
          "reason": "Household expenditure data is an outcome snapshot and needs attribution caution."
        },
        {
          "evidence_id": "E0067",
          "reason": "This is macro-shock context; it should not be treated as a direct ruler failure without more attribution."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence tying 2022 macro and anti-corruption decisions to Hasina personally rather than the finance ministry, central bank, or cabinet",
          "lenses": ["5B.2", "5B.5", "5B.7", "5B.9"],
          "best_source_or_query_direction": "PMO or cabinet records, appointment notices, budget implementation reviews, and audit or investigative material on bank oversight and procurement enforcement",
          "why_it_matters": "Would firm up personal attribution without changing the mixed macro-and-governance picture."
        }
      ],
      "reason": "The package fairly shows mixed economic stewardship: stabilization, reform, and welfare gains alongside inflation, reserve pressure, and corruption. Attribution is mostly indirect, but not fatally so."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0069",
          "reason": "This is a survey of children’s priorities and concerns, not evidence of delivered welfare."
        },
        {
          "evidence_id": "E0073",
          "reason": "WFP strategy language is external planning context, not ruler-level delivery evidence."
        },
        {
          "evidence_id": "E0074",
          "reason": "Food-insecurity figures are outcome context and do not by themselves show specific ruler action."
        },
        {
          "evidence_id": "E0078",
          "reason": "This is a regulatory-gap diagnosis, not a direct Hasina action or decision."
        }
      ],
      "material_gaps": [
        {
          "gap": "More direct 2022 implementation data on beneficiary reach, service quality, and subnational distribution for health, education, protection, and food assistance",
          "lenses": ["6B.2", "6B.3", "6B.4", "6B.5", "6B.10"],
          "best_source_or_query_direction": "Budget execution reports, ministry monitoring data, or independent evaluation of social-program delivery in 2022",
          "why_it_matters": "Would separate stated priorities from delivered welfare gains."
        }
      ],
      "reason": "Fair and balanced on welfare outcomes, but the record is still mostly government-level and outcome-level rather than direct personal stewardship."
    },
    {
      "chapter_id": "7B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0087",
          "reason": "Judicial politicization allegations are country-context evidence, not direct personal integrity proof."
        },
        {
          "evidence_id": "E0088",
          "reason": "Use this only where it shows concealment or retaliation; it should not stand as a general corruption proxy."
        },
        {
          "evidence_id": "E0090",
          "reason": "This is a later retrospective allegation, not an adjudicated finding, and should not be treated as established misconduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 asset, beneficial-ownership, procurement, or family-profit records tied personally to Hasina",
          "lenses": ["7B.3", "7B.4", "7B.9"],
          "best_source_or_query_direction": "Asset declarations, procurement and audit records, parliamentary disclosures, or investigative records tied to the PMO or family",
          "why_it_matters": "This chapter turns on personal nexus; without it, the package leans too much on broad repression context and later allegations."
        },
        {
          "gap": "Clearer proof of personal instruction versus subordinate action on retaliation, concealment, and patronage",
          "lenses": ["7B.6", "7B.7", "7B.8"],
          "best_source_or_query_direction": "Contemporaneous directives, internal correspondence, court records, or detailed investigative reporting that ties the conduct to Hasina personally",
          "why_it_matters": "Would separate the ruler's own integrity pattern from the wider authoritarian environment."
        }
      ],
      "reason": "Usable but not yet tight: it has direct quotes and some direct state actions, yet the self-dealing strand still rests on a later allegation and broader authoritarian context more than on clean 2022 personal records."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0091",
          "reason": "This is program framing, not execution evidence."
        },
        {
          "evidence_id": "E0093",
          "reason": "This is a long-term vision statement, not proof of implementation."
        },
        {
          "evidence_id": "E0095",
          "reason": "Agency-level award reporting is useful context, but it is not direct evidence of Hasina's personal micromanagement."
        },
        {
          "evidence_id": "E0097",
          "reason": "This is a retrospective synthesis with mixed attribution; use it as supporting context, not as standalone proof of personal effectiveness."
        },
        {
          "evidence_id": "E0100",
          "reason": "This is another retrospective outcome claim with only partial attribution to 2022 ruler choices."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence of Hasina personally adapting personnel or strategy in response to 2022 implementation failures",
          "lenses": ["8B.4", "8B.8", "8B.10"],
          "best_source_or_query_direction": "PMO or cabinet change logs, implementation reviews, or contemporaneous reporting on replacement of bottleneck officials",
          "why_it_matters": "Would better separate declared program from actual operational mastery."
        }
      ],
      "reason": "The package is strong and coherent on program articulation, institutional machinery, and some outcome gains, but several outcome claims remain partly macro-level and not tightly personal."
    }
  ]
}
